import React, { useState, useEffect } from 'react';
import axios from 'axios';  // axios import ediyoruz
import './Adminproduct.css';
import PageTitle from '../PageTitle';
import Sidebar from './Sidebar';

const AdminProduct = ({ onEdit, onDelete }) => {
  const [products, setProducts] = useState([]);  // Ürünleri saklayacak state
  const [searchTerm, setSearchTerm] = useState('');
  const [loading, setLoading] = useState(true);  // Yüklenme durumu

  // Ürünleri API'den çekme
  useEffect(() => {
    axios.get('http://localhost:3001/products')
      .then(response => {
        setProducts(response.data);  // API'den gelen ürünleri state'e ekle
        setLoading(false);  // Yükleme işlemi bitti
      })
      .catch(error => {
        console.error('Ürünler alınırken hata oluştu:', error);
        setLoading(false);
      });
  }, []);

  // Arama filtresi
  const filteredProducts = products.filter(product =>
    product.name.toLowerCase().includes(searchTerm.toLowerCase())
  );

  return (
    <>
      <PageTitle title="Ürünler" />
      <div className="admin-container">
        <Sidebar /> {/* Sidebar componenti */}

        <div className="admin-product-container">
          {/* Arama Çubuğu */}
          <input
            type="text"
            className="search-bar"
            placeholder="Ürün ara..."
            value={searchTerm}
            onChange={(e) => setSearchTerm(e.target.value)}
          />

          {/* Yükleme Durumu */}
          {loading ? (
            <p>Ürünler yükleniyor...</p>
          ) : (
            <table className="admin-product-table">
              <thead>
                <tr>
                  <th>Ürün Adı</th>
                  <th>Eklenme Tarihi</th>
                  <th>İşlemler</th>
                </tr>
              </thead>
              <tbody>
                {filteredProducts.length > 0 ? (
                  filteredProducts.map((product) => (
                    <tr key={product.id}>
                      <td>{product.name}</td>
                      <td>{new Date(product.dateAdded).toLocaleDateString()}</td>
                      <td>
                        <button onClick={() => onEdit(product.id)} className="edit-button">
                          Düzenle
                        </button>
                        <button onClick={() => onDelete(product.id)} className="delete-button">
                          Sil
                        </button>
                      </td>
                    </tr>
                  ))
                ) : (
                  <tr>
                    <td colSpan="3">Hiç ürün bulunamadı.</td>
                  </tr>
                )}
              </tbody>
            </table>
          )}
        </div>
      </div>
    </>
  );
};

export default AdminProduct;
